using System.Windows;using OdinVault.Manager.Wpf.ViewModels;namespace OdinVault.Manager.Wpf.Views;public partial class DatabasesView:System.Windows.Controls.UserControl{public DatabasesView(){InitializeComponent();}async void Add_Click(object s,RoutedEventArgs e){if(DataContext is not DatabasesViewModel vm)return;var d=new DatabaseEditWindow{Owner=Window.GetWindow(this)};if(d.ShowDialog()!=true)return;try{var created=await vm.Client.CreateDatabaseAsync(d.CreateRequest);if(created is not null)await vm.Client.TestDatabaseAsync(created.Id);await vm.LoadAsync();}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"OdinVault");}}async void Edit_Click(object s,RoutedEventArgs e){if(DataContext is not DatabasesViewModel vm||vm.Selected is null){System.Windows.MessageBox.Show("ابتدا یک دیتابیس را انتخاب کنید.","OdinVault");return;}try{var db=await vm.Client.GetDatabaseAsync(vm.Selected.Id);if(db is null)return;var d=new DatabaseEditWindow(db){Owner=Window.GetWindow(this)};if(d.ShowDialog()!=true)return;await vm.Client.UpdateDatabaseAsync(db.Id,d.UpdateRequest);await vm.Client.UpdatePolicyAsync(db.Id,d.PolicyRequest);await vm.LoadAsync();}catch(Exception ex){System.Windows.MessageBox.Show(ex.Message,"OdinVault");}}}